window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c6af928e1c357c96"]={"versions": [{"id": "FIG-c6af928e1c357c96", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus dem Paket <code>DataMapping</code> der AUTOSAR-RTE-Spezifikation. Es beschreibt das metamodellbasierte Mapping eines Client-Server-Protokolls (<code>ClientServerToSignalGroupMapping</code>) auf die zugrundeliegenden Signale und Signalgruppen der Systembeschreibung für die Kommunikation über Netzwerke.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist die Metaklasse <code>ClientServerToSignalGroupMapping</code>. Sie referenziert über eine gerichtete Assoziation <code>+signalGroup 1</code> die Klasse <code>SystemSignal::SystemSignalGroup</code> (Stereotyp <code>ARElement</code>), welche ihrerseits über die Komposition <code>+containedSignals 1..<em></code> (Rolle <code>0..1</code>) mit <code>SystemSignal::SystemSignal</code> (<code>ARElement</code>, Attribut <code>+ signalLength: Int</code>) verbunden ist. Zudem verweist das Mapping über <code>«instanceRef» +mappedOperation 1</code> auf <code>PortInterface::OperationPrototype</code> (<code>Identifiable</code>), das wiederum geordnete Argumente <code>+argument </em> {ordered}</code> vom Typ <code>PortInterface::ArgumentPrototype</code> (<code>DataPrototype</code>, Attribut <code>+ direction: DirectionKind</code>) besitzt.</p>\n<p class=\"fig-p\">Über Kompositionen aggregiert <code>ClientServerToSignalGroupMapping</code>:</p>\n<ul class=\"fig-list\">\n<li><code>+clientID 0..1</code>: <code>ClientId</code></li>\n<li><code>+sequenceCounter 0..1</code>: <code>SequenceCounter</code></li>\n<li><code>+applicationError 0..*</code>: <code>ApplicationError</code></li>\n<li><code>+emptySignal 0..1</code>: <code>EmptySignal</code></li>\n<li><code>+primitiveTypeMapping *</code>: <code>ClientServerPrimitiveTypeMapping</code></li>\n<li><code>+compositeTypeMapping *</code>: <code>ClientServerCompositeTypeMapping</code></li>\n</ul>\n<p class=\"fig-p\">Die Klassen <code>ClientId</code>, <code>SequenceCounter</code>, <code>ApplicationError</code>, <code>EmptySignal</code> sowie <code>ClientServerPrimitiveTypeMapping</code> referenzieren jeweils über <code>+systemSignal 1</code> genau ein <code>SystemSignal::SystemSignal</code>. <code>ClientServerPrimitiveTypeMapping</code> referenziert zusätzlich über die Instanzreferenz <code>«instanceRef» +argument 1</code> ein <code>PortInterface::ArgumentPrototype</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm bildet ein statisches Metamodell ab. Es definiert die strukturellen Transformationsregeln, nach denen Client-Server-Aufrufe (Operationen mit Parametern, Client-Identifikatoren, Sequenzzählern zur Zuordnung von Anfragen und Antworten sowie Anwendungsfehler) in diskrete Signale innerhalb einer Signalgruppe serialisiert bzw. abgebildet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für die RTE-Generierung und Systemkonfiguration verbindet das Metamodell Software-Architektur-Schnittstellen (Operationen und Argumente) mit der COM/Signal-Schicht. Signalzuordnungen für Header-Informationen (Client-ID, Sequenzzähler), Statusübertragungen (EmptySignal, ApplicationError) sowie primitive und zusammengesetzte Argumenttypen müssen gemäß den angegebenen Multiplizitäten modelliert werden, um ein standardisiertes Client-Server-Protokoll über serielle Signalübertragungen abzusichern.</p>"}, {"id": "FIG-208cf41dff46a095", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus dem Paket <code>DataMapping</code> der AUTOSAR-RTE-Spezifikation. Es beschreibt das metamodellbasierte Mapping eines Client-Server-Protokolls (<code>ClientServerToSignalGroupMapping</code>) auf die zugrundeliegenden Signale und Signalgruppen der Systembeschreibung für die Kommunikation über Netzwerke.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist die Metaklasse <code>ClientServerToSignalGroupMapping</code>. Sie referenziert über eine gerichtete Assoziation <code>+signalGroup 1</code> die Klasse <code>SystemSignal::SystemSignalGroup</code> (Stereotyp <code>ARElement</code>), welche ihrerseits über die Komposition <code>+containedSignals 1..<em></code> (Rolle <code>0..1</code>) mit <code>SystemSignal::SystemSignal</code> (<code>ARElement</code>, Attribut <code>+ signalLength: Int</code>) verbunden ist. Zudem verweist das Mapping über <code>«instanceRef» +mappedOperation 1</code> auf <code>PortInterface::OperationPrototype</code> (<code>Identifiable</code>), das wiederum geordnete Argumente <code>+argument </em> {ordered}</code> vom Typ <code>PortInterface::ArgumentPrototype</code> (<code>DataPrototype</code>, Attribut <code>+ direction: DirectionKind</code>) besitzt.</p>\n<p class=\"fig-p\">Über Kompositionen aggregiert <code>ClientServerToSignalGroupMapping</code>:</p>\n<ul class=\"fig-list\">\n<li><code>+clientID 0..1</code>: <code>ClientId</code></li>\n<li><code>+sequenceCounter 0..1</code>: <code>SequenceCounter</code></li>\n<li><code>+applicationError 0..*</code>: <code>ApplicationError</code></li>\n<li><code>+emptySignal 0..1</code>: <code>EmptySignal</code></li>\n<li><code>+primitiveTypeMapping *</code>: <code>ClientServerPrimitiveTypeMapping</code></li>\n<li><code>+compositeTypeMapping *</code>: <code>ClientServerCompositeTypeMapping</code></li>\n</ul>\n<p class=\"fig-p\">Die Klassen <code>ClientId</code>, <code>SequenceCounter</code>, <code>ApplicationError</code>, <code>EmptySignal</code> sowie <code>ClientServerPrimitiveTypeMapping</code> referenzieren jeweils über <code>+systemSignal 1</code> genau ein <code>SystemSignal::SystemSignal</code>. <code>ClientServerPrimitiveTypeMapping</code> referenziert zusätzlich über die Instanzreferenz <code>«instanceRef» +argument 1</code> ein <code>PortInterface::ArgumentPrototype</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm bildet ein statisches Metamodell ab. Es definiert die strukturellen Transformationsregeln, nach denen Client-Server-Aufrufe (Operationen mit Parametern, Client-Identifikatoren, Sequenzzählern zur Zuordnung von Anfragen und Antworten sowie Anwendungsfehler) in diskrete Signale innerhalb einer Signalgruppe serialisiert bzw. abgebildet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für die RTE-Generierung und Systemkonfiguration verbindet das Metamodell Software-Architektur-Schnittstellen (Operationen und Argumente) mit der COM/Signal-Schicht. Signalzuordnungen für Header-Informationen (Client-ID, Sequenzzähler), Statusübertragungen (EmptySignal, ApplicationError) sowie primitive und zusammengesetzte Argumenttypen müssen gemäß den angegebenen Multiplizitäten modelliert werden, um ein standardisiertes Client-Server-Protokoll über serielle Signalübertragungen abzusichern.</p>"}, {"id": "FIG-ee77b8dc35d1d0e3", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus dem Paket <code>DataMapping</code> der AUTOSAR-RTE-Spezifikation. Es modelliert das Metamodell für das Mapping standardisierter Client-Server-Kommunikation auf Signalgruppen und Einzelsignale der Systembeschreibung (<code>CoreCommunication</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist <code>ClientServerToSignalGroupMapping</code>. Sie referenziert <code>CoreCommunication::SystemSignalGroup</code> (<code>AbstractSignal</code>) über zwei getrennte Rollen: <code>+requestGroup 1</code> und <code>+responseGroup 0..1</code>. <code>CoreCommunication::SystemSignalGroup</code> verweist über <code>+systemSignal *</code> auf <code>CoreCommunication::SystemSignal</code> (<code>AbstractSignal</code>, Attribut <code>+ length :Integer</code>).</p>\n<p class=\"fig-p\"><code>ClientServerToSignalGroupMapping</code> aggregiert über Kompositionen folgende Mapping-Elemente:</p>\n<ul class=\"fig-list\">\n<li><code>+clientID 0..1</code>: <code>ClientIdMapping</code></li>\n<li><code>+sequenceCounter 0..1</code>: <code>SequenceCounterMapping</code></li>\n<li><code>+applicationError 0..*</code>: <code>ApplicationErrorMapping</code></li>\n<li><code>+emptySignal 0..1</code>: <code>EmptySignalMapping</code></li>\n<li><code>+primitiveTypeMapping *</code>: <code>ClientServerPrimitiveTypeMapping</code></li>\n<li><code>+compositeTypeMapping *</code>: <code>ClientServerCompositeTypeMapping</code></li>\n</ul>\n<p class=\"fig-p\">Jedes der Elemente <code>ClientIdMapping</code>, <code>SequenceCounterMapping</code>, <code>ApplicationErrorMapping</code>, <code>EmptySignalMapping</code> sowie <code>ClientServerPrimitiveTypeMapping</code> referenziert über die gerichtete Assoziation <code>+systemSignal 1</code> jeweils genau ein <code>CoreCommunication::SystemSignal</code>. Eine direkte Modellierung von OperationPrototypes oder ArgumentPrototypes ist in dieser Sicht nicht enthalten.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm bildet ein statisches Metamodell ab. Es definiert die strukturellen Transformationsregeln, nach denen Client-Server-Aufrufe (Operationen mit Parametern, Client-Identifikatoren, Sequenzzählern zur Zuordnung von Anfragen und Antworten sowie Anwendungsfehler) in diskrete Signale innerhalb einer Signalgruppe serialisiert bzw. abgebildet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Metamodell trennt explizit zwischen Request-Signalgruppe (verpflichtend mit Kardinalität 1) und Response-Signalgruppe (optional mit Kardinalität 0..1). Werkzeuge zur Signal- und RTE-Konfiguration müssen Einzelsignale für Client-Identifikation, Sequenzzähler, Anwendungsfehler und Datenelemente den Signalen der jeweiligen Signalgruppe zuordnen, wobei die Signallänge nun über <code>length :Integer</code> typisiert ist.</p>"}, {"id": "FIG-115904b338323ace", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus dem Paket <code>DataMapping</code> der AUTOSAR-RTE-Spezifikation. Es modelliert das Metamodell für das Mapping standardisierter Client-Server-Kommunikation auf Signalgruppen und Einzelsignale der Systembeschreibung (<code>CoreCommunication</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist <code>ClientServerToSignalGroupMapping</code>. Sie referenziert <code>CoreCommunication::SystemSignalGroup</code> (<code>ARElement</code>) über die gerichteten Rollen <code>+responseGroup 1</code> und <code>+requestGroup 0..1</code>. <code>CoreCommunication::SystemSignalGroup</code> referenziert über <code>+systemSignal *</code> die Metaklasse <code>CoreCommunication::SystemSignal</code> (<code>ARElement</code>, Attribut <code>+ dynamicLength: Boolean</code>).</p>\n<p class=\"fig-p\"><code>ClientServerToSignalGroupMapping</code> aggregiert über Kompositionen folgende Mapping-Elemente:</p>\n<ul class=\"fig-list\">\n<li><code>+clientID 0..1</code>: <code>ClientIdMapping</code></li>\n<li><code>+sequenceCounter 0..1</code>: <code>SequenceCounterMapping</code></li>\n<li><code>+applicationError 0..1</code>: <code>ApplicationErrorMapping</code></li>\n<li><code>+emptySignal 0..1</code>: <code>EmptySignalMapping</code></li>\n<li><code>+primitiveTypeMapping *</code>: <code>ClientServerPrimitiveTypeMapping</code></li>\n<li><code>+compositeTypeMapping *</code>: <code>ClientServerCompositeTypeMapping</code></li>\n</ul>\n<p class=\"fig-p\">Die Entitäten <code>ClientIdMapping</code>, <code>SequenceCounterMapping</code>, <code>ApplicationErrorMapping</code>, <code>EmptySignalMapping</code> und <code>ClientServerPrimitiveTypeMapping</code> verweisen über die Assoziation <code>+systemSignal 1</code> jeweils auf genau ein <code>CoreCommunication::SystemSignal</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm bildet ein statisches Metamodell ab. Es definiert die strukturellen Transformationsregeln, nach denen Client-Server-Aufrufe (Operationen mit Parametern, Client-Identifikatoren, Sequenzzählern zur Zuordnung von Anfragen und Antworten sowie Anwendungsfehler) in diskrete Signale innerhalb einer Signalgruppe serialisiert bzw. abgebildet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Rollenverteilung ordnet der Response-Gruppe die feste Multiplizität 1 und der Request-Gruppe die optionale Multiplizität 0..1 zu. <code>ApplicationErrorMapping</code> ist auf maximal eine Instanz beschränkt (<code>0..1</code>). Die Signalspezifikation unterstützt über das boolesche Attribut <code>dynamicLength</code> Signale variabler Länge, was von Codegeneratoren und RTE-Laufzeitumgebungen bei der Serialisierung und Deserialisierung berücksichtigt werden muss.</p>"}], "trans": [{"from": "FIG-c6af928e1c357c96", "to": "FIG-208cf41dff46a095", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-208cf41dff46a095", "to": "FIG-ee77b8dc35d1d0e3", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>ClientServerToSignalGroupMapping</code>: Assoziation zu <code>SystemSignalGroup</code> aufgeteilt in <code>+requestGroup 1</code> und <code>+responseGroup 0..1</code> (vorher <code>+signalGroup 1</code>).</li>\n<li>Entfall der Klassen <code>PortInterface::OperationPrototype</code> und <code>PortInterface::ArgumentPrototype</code> samt der Assoziationen <code>+mappedOperation 1</code> und <code>+argument 1</code>.</li>\n<li>Umbenennung der Kompositionsklassen: <code>ClientId</code> zu <code>ClientIdMapping</code>, <code>SequenceCounter</code> zu <code>SequenceCounterMapping</code>, <code>ApplicationError</code> zu <code>ApplicationErrorMapping</code> sowie <code>EmptySignal</code> zu <code>EmptySignalMapping</code>.</li>\n<li><code>SystemSignalGroup</code> und <code>SystemSignal</code>: Paketpräfix von <code>SystemSignal::</code> zu <code>CoreCommunication::</code> geändert; Stereotyp/Basisklasse von <code>ARElement</code> zu <code>AbstractSignal</code> geändert.</li>\n<li><code>SystemSignalGroup</code>: Assoziation zu <code>SystemSignal</code> von <code>+containedSignals 1..<em></code> (mit Rückrollen-Multiplizität <code>0..1</code>) zu ungerichteter/gerichteter Assoziation <code>+systemSignal </em></code> geändert.</li>\n<li><code>SystemSignal</code>: Attribut <code>+ signalLength: Int</code> geändert zu <code>+ length :Integer</code>.</li>\n</ul>"}, {"from": "FIG-ee77b8dc35d1d0e3", "to": "FIG-115904b338323ace", "fr": "R3.2.3", "tr": "R4.0.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>ClientServerToSignalGroupMapping</code>: Rollenmultiplizitäten zu <code>CoreCommunication::SystemSignalGroup</code> vertauscht von <code>+requestGroup 1</code> / <code>+responseGroup 0..1</code> zu <code>+responseGroup 1</code> / <code>+requestGroup 0..1</code>.</li>\n<li><code>ClientServerToSignalGroupMapping</code>: Kompositionsmultiplizität <code>+applicationError</code> von <code>0..*</code> auf <code>0..1</code> reduziert.</li>\n<li><code>CoreCommunication::SystemSignalGroup</code> und <code>CoreCommunication::SystemSignal</code>: Stereotyp/Basisklasse von <code>AbstractSignal</code> zurückgeändert zu <code>ARElement</code>.</li>\n<li><code>CoreCommunication::SystemSignal</code>: Attribut <code>+ length :Integer</code> ersetzt durch <code>+ dynamicLength: Boolean</code>.</li>\n</ul>"}]};
